function merge(a, b) {
  const result = [];
  let i = 0, j = 0;
  while (i < a.length && j < b.length) {
    if (a[i] <= b[j]) result.push(a[i++]);   // take the smaller front
    else result.push(b[j++]);
  }
  while (i < a.length) result.push(a[i++]);  // copy what's left
  while (j < b.length) result.push(b[j++]);
  return result;
}

class Solution {
    public int[] merge(int[] a, int[] b) {
        int[] result = new int[a.length + b.length];
        int i = 0, j = 0, k = 0;
        while (i < a.length && j < b.length) {
            if (a[i] <= b[j]) result[k++] = a[i++];   // take the smaller front
            else result[k++] = b[j++];
        }
        while (i < a.length) result[k++] = a[i++];   // copy what's left
        while (j < b.length) result[k++] = b[j++];
        return result;
    }
}

class Solution {
public:
    vector<int> merge(vector<int>& a, vector<int>& b) {
        vector<int> result;
        result.reserve(a.size() + b.size());
        size_t i = 0, j = 0;
        while (i < a.size() && j < b.size()) {
            if (a[i] <= b[j]) result.push_back(a[i++]);   // take the smaller front
            else result.push_back(b[j++]);
        }
        while (i < a.size()) result.push_back(a[i++]);   // copy what's left
        while (j < b.size()) result.push_back(b[j++]);
        return result;
    }
};
